/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_f32]_m)
 */
public fun svabdF32M(pg: SvboolT, op1: Svfloat32T, op2: Svfloat32T): Svfloat32T {
    fun svabdF32M(pg1: Svbool4T, op11: Svfloat32T, op21: Svfloat32T): Svfloat32T = run { val ptr = kmAllocZeroed(maxOf(1L, (ObjectSlotLayout<Svfloat32T>()).sizeBytes), maxOf(1L, (ObjectSlotLayout<Svfloat32T>()).alignBytes)); val res = (ObjectSlotLayout<Svfloat32T>()).readNative(ptr); kmDealloc(ptr, maxOf(1L, (ObjectSlotLayout<Svfloat32T>()).sizeBytes), maxOf(1L, (ObjectSlotLayout<Svfloat32T>()).alignBytes)); res }
    return svabdF32M(pg.sveInto(), op1, op2)
}

/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_n_f32]_m)
 */
public fun svabdNF32M(pg: SvboolT, op1: Svfloat32T, op2: Float): Svfloat32T = svabdF32M(pg, op1, svdupNF32(op2))

/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_f32]_x)
 */
public fun svabdF32X(pg: SvboolT, op1: Svfloat32T, op2: Svfloat32T): Svfloat32T = svabdF32M(pg, op1, op2)

/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_n_f32]_x)
 */
public fun svabdNF32X(pg: SvboolT, op1: Svfloat32T, op2: Float): Svfloat32T = svabdF32X(pg, op1, svdupNF32(op2))

/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_f32]_z)
 */
public fun svabdF32Z(pg: SvboolT, op1: Svfloat32T, op2: Svfloat32T): Svfloat32T = svabdF32M(pg, svselF32(pg, op1, svdupNF32(0.0f)), op2)

/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_n_f32]_z)
 */
public fun svabdNF32Z(pg: SvboolT, op1: Svfloat32T, op2: Float): Svfloat32T = svabdF32Z(pg, op1, svdupNF32(op2))

/**
 * Absolute difference
 * [Arm's documentation](https://developer.arm.com/architectures/instruction-sets/intrinsics/svabd[_f64]_m)
 */
public fun svabdF64M(pg: SvboolT, op1: Svfloat64T, op2: Svfloat64T): Svfloat64T {
    fun svabdF64M(pg1: Svbool2T, op11: Svfloat64T, op21: Svfloat64T): Svfloat64T = run { val ptr = kmAllocZeroed(maxOf(1L, (ObjectSlotLayout<Svfloat64T>()).sizeBytes), maxOf(1L, (ObjectSlotLayout<Svfloat64T>()).alignBytes)); val res = (ObjectSlotLayout<Svfloat64T>()).readNative(ptr); kmDealloc(ptr, maxOf(1L, (ObjectSlotLayout<Svfloat64T>()).sizeBytes), maxOf(1L, (ObjectSlotLayout<Svfloat64T>()).alignBytes)); res }
    return svabdF64M(pg.sveInto(), op1, op2)
}

